'use client'

import { useState } from 'react'
import { FiPlus, FiFolder, FiFileText, FiMessageSquare, FiMoreVertical } from 'react-icons/fi'

interface Project {
  id: string
  name: string
  description: string
  docCount: number
  chatCount: number
  updatedAt: Date
  color: string
}

const MOCK_PROJECTS: Project[] = [
  { id: 'p1', name: 'Q3 Reporting', description: 'Financial reports and analysis for Q3', docCount: 6, chatCount: 3, updatedAt: new Date(Date.now() - 3600_000), color: 'from-blue-500 to-purple-600' },
  { id: 'p2', name: 'Client Contracts', description: 'Contract review and redlining', docCount: 12, chatCount: 8, updatedAt: new Date(Date.now() - 86400_000), color: 'from-emerald-500 to-teal-600' },
  { id: 'p3', name: 'Research Archive', description: 'Reference material and notes', docCount: 4, chatCount: 1, updatedAt: new Date(Date.now() - 259200_000), color: 'from-amber-500 to-orange-600' },
]

export default function ProjectsView() {
  const [projects] = useState<Project[]>(MOCK_PROJECTS)

  return (
    <div className="flex-1 flex flex-col overflow-hidden">
      <div className="border-b border-[var(--border-subtle)] bg-[var(--surface)] backdrop-blur-xl px-6 py-4 flex items-center justify-between">
        <h1 className="text-xl font-bold text-[var(--text-primary)]">Projects</h1>
        <button className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white text-sm font-medium rounded-xl transition-all shadow-lg shadow-blue-500/30">
          <FiPlus className="w-4 h-4" />
          New project
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-6">
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          {projects.map(project => (
            <div
              key={project.id}
              className="bg-[var(--surface-soft)] hover:bg-[var(--surface-strong)] border border-[var(--border-subtle)] rounded-2xl p-5 cursor-pointer transition-all duration-200"
            >
              <div className="flex items-start justify-between mb-4">
                <div className={`w-10 h-10 bg-gradient-to-br ${project.color} rounded-xl flex items-center justify-center`}>
                  <FiFolder className="w-5 h-5 text-white" />
                </div>
                <button onClick={e => e.stopPropagation()} className="p-1.5 hover:bg-[var(--surface-strong)] rounded-lg transition-colors">
                  <FiMoreVertical className="w-4 h-4 text-[var(--text-muted)]" />
                </button>
              </div>
              <h3 className="text-sm font-semibold text-[var(--text-primary)] mb-1">{project.name}</h3>
              <p className="text-xs text-[var(--text-muted)] mb-4 line-clamp-2">{project.description}</p>
              <div className="flex items-center gap-4 text-xs text-[var(--text-muted)]">
                <span className="flex items-center gap-1.5">
                  <FiFileText className="w-3.5 h-3.5" />
                  {project.docCount} docs
                </span>
                <span className="flex items-center gap-1.5">
                  <FiMessageSquare className="w-3.5 h-3.5" />
                  {project.chatCount} chats
                </span>
                <span className="ml-auto">{project.updatedAt.toLocaleDateString()}</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}