'use client'

import { useState, useRef, useEffect } from 'react'
import { FiPlus, FiSend, FiMic, FiMoreVertical, FiPaperclip, FiLoader, FiMenu, FiX } from 'react-icons/fi'

interface Message {
  id: string
  sender: 'user' | 'assistant'
  content: string
  timestamp: Date
}

interface Conversation {
  id: string
  title: string
  lastMessage: string
  date: Date
}

export default function ChatView() {
  const [isClient, setIsClient] = useState(false)
  const [listOpen, setListOpen] = useState(true)

  const [conversations, setConversations] = useState<Conversation[]>([
    { id: '1', title: 'Document Analysis', lastMessage: 'How can I improve...', date: new Date() },
    { id: '2', title: 'Data Extraction', lastMessage: 'Extract tables from...', date: new Date(Date.now() - 86400000) },
  ])

  const [messages, setMessages] = useState<Message[]>([
    { id: '1', sender: 'assistant', content: "Hello! I'm your AI Document Agent. How can I help you today?", timestamp: new Date() },
  ])

  const [input, setInput] = useState('')
  const [isRecording, setIsRecording] = useState(false)
  const [isSending, setIsSending] = useState(false)
  const [selectedConversation, setSelectedConversation] = useState('1')
  const messagesEndRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    setIsClient(true)
  }, [])

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!input.trim()) return

    setIsSending(true)
    const userMessage: Message = {
      id: Date.now().toString(),
      sender: 'user',
      content: input,
      timestamp: new Date(),
    }
    setMessages(prev => [...prev, userMessage])
    setInput('')

    // TODO: replace with a real call to the FastAPI backend
    setTimeout(() => {
      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        sender: 'assistant',
        content: 'I received your message. This is a placeholder response from the AI agent.',
        timestamp: new Date(),
      }
      setMessages(prev => [...prev, assistantMessage])
      setIsSending(false)
    }, 1000)
  }

  const handleNewChat = () => {
    const newConversation: Conversation = {
      id: Date.now().toString(),
      title: 'New conversation',
      lastMessage: 'Just started',
      date: new Date(),
    }
    setConversations(prev => [newConversation, ...prev])
    setSelectedConversation(newConversation.id)
    setMessages([])
  }

  if (!isClient) {
    return null
  }

  return (
    <div className="flex flex-1 overflow-hidden">
      {/* Conversation list */}
      <aside
        className={`${
          listOpen ? 'w-64' : 'w-0'
        } bg-[var(--surface)] backdrop-blur-xl border-r border-[var(--border-subtle)] flex flex-col transition-all duration-300 overflow-hidden shrink-0`}
      >
        <div className="p-4 border-b border-[var(--border-subtle)] flex items-center justify-between">
          <h2 className="text-sm font-semibold text-[var(--text-secondary)] uppercase tracking-wide">Conversations</h2>
          <button onClick={handleNewChat} className="p-2 hover:bg-[var(--surface-strong)] rounded-lg transition-colors">
            <FiPlus className="w-4 h-4 text-[var(--text-secondary)]" />
          </button>
        </div>
        <div className="flex-1 overflow-y-auto">
          {conversations.map(conv => (
            <div
              key={conv.id}
              onClick={() => setSelectedConversation(conv.id)}
              className={`p-3 mx-2 my-1 rounded-xl cursor-pointer transition-all duration-200 ${
                selectedConversation === conv.id
                  ? 'bg-blue-600/30 border border-blue-500/50 backdrop-blur'
                  : 'hover:bg-[var(--surface-soft)]'
              }`}
            >
              <p className="font-medium text-[var(--text-primary)] text-sm truncate">{conv.title}</p>
              <p className="text-xs text-[var(--text-muted)] truncate">{conv.lastMessage}</p>
              <p className="text-xs text-[var(--text-muted)] mt-1">{conv.date.toLocaleDateString()}</p>
            </div>
          ))}
        </div>
      </aside>

      {/* Thread */}
      <div className="flex-1 flex flex-col">
        {/* Header */}
        <div className="border-b border-[var(--border-subtle)] bg-[var(--surface)] backdrop-blur-xl px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button onClick={() => setListOpen(!listOpen)} className="p-2 hover:bg-[var(--surface-strong)] rounded-lg transition-colors">
              {listOpen ? <FiX className="w-5 h-5 text-[var(--text-secondary)]" /> : <FiMenu className="w-5 h-5 text-[var(--text-secondary)]" />}
            </button>
            <h1 className="text-xl font-bold text-transparent bg-gradient-to-r from-blue-400 to-purple-400 bg-clip-text">
              {conversations.find(c => c.id === selectedConversation)?.title || 'Chat'}
            </h1>
          </div>
          <button className="p-2 hover:bg-[var(--surface-strong)] rounded-lg transition-colors">
            <FiMoreVertical className="w-5 h-5 text-[var(--text-secondary)]" />
          </button>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {messages.length === 0 ? (
            <div className="h-full flex items-center justify-center">
              <div className="text-center">
                <div className="inline-block p-4 bg-gradient-to-br from-blue-500/20 to-purple-600/20 rounded-2xl mb-4">
                  <svg className="w-12 h-12 text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                  </svg>
                </div>
                <h2 className="text-2xl font-bold text-[var(--text-primary)] mb-2">Start a conversation</h2>
                <p className="text-[var(--text-secondary)]">Ask me anything about documents, analysis, or data</p>
              </div>
            </div>
          ) : (
            <>
              {messages.map(message => (
                <div key={message.id} className={`flex ${message.sender === 'user' ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
                  <div
                    className={`max-w-xs lg:max-w-md px-4 py-3 rounded-2xl backdrop-blur-sm transition-all ${
                      message.sender === 'user'
                        ? 'bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-br-none shadow-lg shadow-blue-500/20'
                        : 'bg-[var(--surface-strong)] border border-[var(--border-strong)] text-[var(--text-primary)] rounded-bl-none'
                    }`}
                  >
                    <p className="text-sm leading-relaxed">{message.content}</p>
                    <p className={`text-xs mt-2 ${message.sender === 'user' ? 'text-blue-100' : 'text-[var(--text-muted)]'}`}>
                      {isClient ? message.timestamp.toLocaleTimeString() : ''}
                    </p>
                  </div>
                </div>
              ))}
              {isSending && (
                <div className="flex justify-start">
                  <div className="bg-[var(--surface-strong)] border border-[var(--border-strong)] text-[var(--text-primary)] px-4 py-3 rounded-2xl rounded-bl-none backdrop-blur-sm">
                    <div className="flex gap-2">
                      <div className="w-2 h-2 bg-[var(--text-secondary)] rounded-full animate-bounce"></div>
                      <div className="w-2 h-2 bg-[var(--text-secondary)] rounded-full animate-bounce animation-delay-100"></div>
                      <div className="w-2 h-2 bg-[var(--text-secondary)] rounded-full animate-bounce animation-delay-200"></div>
                    </div>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </>
          )}
        </div>

        {/* Input */}
        <div className="border-t border-[var(--border-subtle)] bg-[var(--surface)] backdrop-blur-xl p-4">
          <form onSubmit={handleSendMessage} className="flex gap-3">
            <button type="button" className="p-3 bg-[var(--surface-strong)] hover:bg-[var(--surface-hover-strong)] border border-[var(--border-strong)] rounded-xl transition-all">
              <FiPaperclip className="w-5 h-5 text-[var(--text-secondary)]" />
            </button>
            <input
              type="text"
              value={input}
              onChange={e => setInput(e.target.value)}
              placeholder="Message AI Agent..."
              className="flex-1 px-4 py-3 bg-[var(--surface-strong)] border border-[var(--border-strong)] rounded-xl text-[var(--text-primary)] placeholder-[var(--text-muted)] focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500/50 backdrop-blur-sm transition-all duration-200"
            />
            <button
              type="button"
              onClick={() => setIsRecording(!isRecording)}
              className={`p-3 rounded-xl transition-all ${
                isRecording ? 'bg-red-600 text-white' : 'bg-[var(--surface-strong)] hover:bg-[var(--surface-hover-strong)] border border-[var(--border-strong)] text-[var(--text-secondary)]'
              }`}
            >
              <FiMic className="w-5 h-5" />
            </button>
            <button
              type="submit"
              disabled={isSending || !input.trim()}
              className="p-3 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white rounded-xl transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-blue-500/30"
            >
              {isSending ? <FiLoader className="w-5 h-5 animate-spin" /> : <FiSend className="w-5 h-5" />}
            </button>
          </form>
          <p className="text-xs text-[var(--text-muted)] mt-2 px-4">
            💡 Tip: Press Shift+Enter for new line. Attach files using the paperclip button.
          </p>
        </div>
      </div>
    </div>
  )
}